fn merge_sort(a: &mut [i32], l: usize, r: usize, count: &mut usize) {
    let m = (l + r) / 2;
    merge_sort(a, l, m, count);
    merge_sort(a, m + 1, r, count);
    let (mut i, mut j) = (l, m + 1);
    while i <= m && j <= r {
        if a[i] < a[j] {
            temp.push(a[i]);
            i += 1;
        } else {
            temp.push(a[j]);
            j += 1;
            *count += m - i + 1;
        }
    }
    print!("merge [{}..{}]:", l, r);
    for n in &a[l..=r] {
        print!(" {}", n);
    }
    println!();
